@Mixin(KeyboardHandler.class)
public abstract class PurpleSkipMixin {
    @Inject(method = "keyPress", at = @At("HEAD"), cancellable = true)
    private void godwand$skipPurple(long window, int action, net.minecraft.client.input.KeyEvent event, CallbackInfo ci) {
        var client = Minecraft.getInstance();
        if (window == client.getWindow().handle() && event.key() == GLFW.GLFW_KEY_ESCAPE && action == GLFW.GLFW_PRESS && client.screen == null && PurpleCinematic.active()) {
            PurpleCinematic.skip();
            ci.cancel();
